<?php
namespace App\Http\Controllers;
use App\Models\OrganizationMembership; use App\Models\AttendanceSession; use App\Services\AttendanceService; use Illuminate\Http\Request;
class AttendanceController extends Controller
{
    public function __construct(private AttendanceService $attendance) {}
    private function actor(Request $r): OrganizationMembership { return $r->attributes->get('currentMembership'); }
    public function index(Request $r) { $actor=$this->actor($r); abort_if(app(\App\Services\WorkspaceAccess::class)->scopes($actor,'attendance.view')===[],403);
        // Claude, 2026-10-29: the list was unscoped, so any attendance.view
        // scope read the whole organization's sessions. Narrowed to the same
        // member set the CSV export below already uses.
        $visible=app(\App\Services\WorkspaceAccess::class)->visibleMembers($actor,'attendance.view')->select('id');
        $query=AttendanceSession::where('organization_id',$actor->organization_id)->whereIn('membership_id',$visible)->with('membership.user');
        if($r->filled('membership_id'))$query->where('membership_id',$r->integer('membership_id')); $page=$query->latest('clocked_in_at')->paginate(50); if($r->expectsJson()){return response()->json($page);} return view('workspace.attendance.index',['page'=>$page,'actor'=>$actor,'open'=>AttendanceSession::where('organization_id',$actor->organization_id)->where('membership_id',$actor->id)->whereNull('clocked_out_at')->first(),'corrections'=>\App\Models\AttendanceCorrectionRequest::where('organization_id',$actor->organization_id)->where(fn($q)=>$q->where('membership_id',$actor->id)->orWhere('status','pending'))->with('membership.user')->latest()->limit(25)->get()]); }
    public function clockIn(Request $r) { $session=$this->attendance->clockIn($this->actor($r)); return $r->expectsJson()?response()->json(['data'=>$session],201):redirect()->route('attendance.index')->with('success','Clocked in.'); }
    public function clockOut(Request $r) { $session=$this->attendance->clockOut($this->actor($r)); return $r->expectsJson()?response()->json(['data'=>$session]):redirect()->route('attendance.index')->with('success','Clocked out.'); }
    public function correct(Request $r) { $correction=$this->attendance->requestCorrection($this->actor($r),$r->all()); return $r->expectsJson()?response()->json(['data'=>$correction],201):redirect()->route('attendance.index')->with('success','Correction requested.'); }
    public function summary(Request $r) { $data=$r->validate(['from'=>['required','date_format:Y-m-d'],'to'=>['required','date_format:Y-m-d','after_or_equal:from']]); return response()->json(['data'=>$this->attendance->summary($this->actor($r),$data['from'],$data['to'])]); }
    public function export(Request $r): \Symfony\Component\HttpFoundation\StreamedResponse { $a=$this->actor($r); app(\App\Services\WorkspaceAccess::class)->authorize($a,'attendance.export'); $data=$r->validate(['from'=>['required','date_format:Y-m-d'],'to'=>['required','date_format:Y-m-d','after_or_equal:from']]); $visible=app(\App\Services\WorkspaceAccess::class)->visibleMembers($a,'attendance.view')->select('id'); $rows=AttendanceSession::where('organization_id',$a->organization_id)->whereIn('membership_id',$visible)->whereBetween('local_date',[$data['from'],$data['to']])->with('membership.user')->orderBy('local_date')->cursor(); return response()->streamDownload(function()use($rows){$out=fopen('php://output','w');fputcsv($out,['date','employee','clocked_in_at','clocked_out_at','minutes','status']);foreach($rows as $row)fputcsv($out,[$row->local_date->toDateString(),$row->membership->user->name,$row->clocked_in_at?->toIso8601String(),$row->clocked_out_at?->toIso8601String(),$row->duration_minutes,$row->status]);fclose($out);},'attendance.csv',['Content-Type'=>'text/csv']); }
    public function decide(Request $r,int $correction) { $request=\App\Models\AttendanceCorrectionRequest::where('organization_id',$this->actor($r)->organization_id)->findOrFail($correction); $data=$r->validate(['decision'=>['required','in:approved,rejected']]); $decided=$this->attendance->decideCorrection($this->actor($r),$request,$data['decision']); return $r->expectsJson()?response()->json(['data'=>$decided]):redirect()->route('attendance.index')->with('success','Correction '.$data['decision'].'.'); }
    public function register(Request $r) { $a=$this->actor($r); app(\App\Services\WorkspaceAccess::class)->authorize($a,'attendance.view'); $date=$r->validate(['date'=>['required','date_format:Y-m-d']])['date']; $members=app(\App\Services\WorkspaceAccess::class)->visibleMembers($a,'attendance.view')->with('user')->get();$sessions=AttendanceSession::where('organization_id',$a->organization_id)->whereDate('local_date',$date)->whereIn('membership_id',$members->modelKeys())->get()->groupBy('membership_id');return response()->json(['date'=>$date,'rows'=>$members->map(fn($m)=>['membership_id'=>$m->id,'employee'=>$m->user->name,'sessions'=>$sessions->get($m->id,collect())->values()])->values()]); }
}
